"""Photos: every file is CC0 or CC BY-SA from Wikimedia Commons, licence checked on the file page on 8 Oct 2026.
Source data: /workspace/animal-sites/big-cats/photos/chosen.json. Images are cropped to 3:2 and saved as WebP at 960 and 480 px wide."""
import html, os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
def have(slug):
    """True once the resized WebP files exist (made by photos/batch.py). Pages skip photos until then."""
    return all(os.path.exists(os.path.join(ROOT, "img", "%s-%d.webp" % (slug, w))) for w in (480, 960))

