PHOTOS = {p["used_on"]: p for p in PHOTOS_LIST}

def credit_line(p):
    lic = '<a href="%s" rel="license noopener">%s</a>' % (html.escape(p["licurl"]), p["lic"])
    return 'Photo: %s, %s, via <a href="%s" rel="noopener">Wikimedia Commons</a>' % (html.escape(p["author"]), lic, html.escape(p["page"]))

def photo_html(path, rel, lazy=True):
    p = PHOTOS[path]; s = rel + "img/" + p["slug"]
    if not have(p["slug"]):
        return ""
    load = ' loading="lazy"' if lazy else ' fetchpriority="high"'
    return ('<figure class="photo"><img src="%s-960.webp" srcset="%s-480.webp 480w, %s-960.webp 960w" sizes="(max-width: 1000px) 94vw, 940px" '
            'width="960" height="640" alt="%s"%s decoding="async"><figcaption>%s. %s.</figcaption></figure>') % (
            s, s, s, html.escape(p["alt"]), load, html.escape(p["alt"]), credit_line(p))
